def sheet(name,data):
 s=w.create_sheet(name);s.append(headers)
 for r in data:s.append(r)
 if data:
  tab=Table(displayName='T'+str(len(w.worksheets)),ref=s.dimensions);tab.tableStyleInfo=TableStyleInfo(name='TableStyleMedium4',showRowStripes=True);s.add_table(tab)
 s.freeze_panes='C2';s.sheet_view.zoomScale=80
 for i,width in enumerate([12,45,55,31,25,85,31,24,26,52,16,12],1):s.column_dimensions[openpyxl.utils.get_column_letter(i)].width=width
 for r in s.iter_rows(min_row=2):
  widths=[12,45,55,31,25,85,31,24,26,52,16,12]
  lines=max(sum(max(1,math.ceil(len(part)/(widths[i]-3))) for part in str(c.value or '').splitlines()) for i,c in enumerate(r))
  s.row_dimensions[r[0].row].height=min(350,max(65,lines*16+12))
  color={'Закрыто':'DCF0DE','На согласовании':'FFF0CD','Частично':'E5EDFA','Не делаем':'E5E5E5','Не выполнено':'FBE4DD'}.get(r[4].value,'F4F1EB');r[4].fill=PatternFill('solid',fgColor=color)
 s.column_dimensions['L'].hidden=True
 return s
